$ErrorActionPreference = 'SilentlyContinue'
Write-Output "=== TIME: $(Get-Date -Format o) ==="
Write-Output "=== HEALTH ==="
try {
  $r = Invoke-WebRequest -Uri http://127.0.0.1:1933/health -TimeoutSec 5 -UseBasicParsing
  Write-Output "HTTP $($r.StatusCode): $($r.Content)"
} catch {
  Write-Output "OV_DOWN: $($_.Exception.Message)"
}
Write-Output "=== PORT 1933 LISTEN ==="
$conns = Get-NetTCPConnection -LocalPort 1933 -State Listen -ErrorAction SilentlyContinue
if ($conns) { $conns | Select-Object LocalAddress,LocalPort,OwningProcess | Format-Table -AutoSize | Out-String | Write-Output }
else { Write-Output "NO_LISTENER" }
Write-Output "=== OLLAMA 11434 ==="
try {
  $o = Invoke-WebRequest -Uri http://127.0.0.1:11434/api/tags -TimeoutSec 5 -UseBasicParsing
  Write-Output "OLLAMA_OK HTTP $($o.StatusCode)"
} catch { Write-Output "OLLAMA_DOWN: $($_.Exception.Message)" }
Write-Output "=== PROCESSES (openviking / python) ==="
Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'openviking|python' } | Select-Object ProcessId,ParentProcessId,Name,CommandLine | Format-List | Out-String -Width 400 | Write-Output
Write-Output "=== SERVER.LOG TAIL 30 ==="
$log = Join-Path $env:USERPROFILE '.openviking\server.log'
if (Test-Path $log) { Get-Content $log -Tail 30 } else { Write-Output "NO_LOG: $log" }
Write-Output "=== END ==="

