import json, urllib.request
for u in ["http://127.0.0.1:1933/openapi.json", "http://127.0.0.1:1933/api/openapi.json", "http://127.0.0.1:1933/docs"]:
    try:
        with urllib.request.urlopen(u, timeout=8) as r:
            b = r.read().decode("utf-8", "replace")
            print("URL", u, r.status, "len", len(b))
            if "openapi" in u:
                d = json.loads(b)
                paths = [p for p in d.get("paths", {}) if "search" in p or "find" in p]
                print("  SEARCH_PATHS:", paths[:30])
                print("  SAMPLE_ALL:", list(d.get("paths", {}))[:20])
    except Exception as e:
        print("URL", u, "ERR", repr(e))

